<?php use App\Helpers\{View,Csrf};?><div class="admin-head"><div><span class="eyebrow">INVENTARIO</span><h1>Productos</h1></div><a class="primary btn" href="/admin/products/create">+ Nuevo producto</a></div><div class="table-wrap"><table><thead><tr><th>Producto</th><th>Categoría</th><th>Precio</th><th>Stock</th><th>Puntos</th><th>Estado</th><th></th></tr></thead><tbody><?php foreach($products as $p):?><tr><td><b><?=View::e($p['name'])?></b></td><td><?=View::e($p['category_name'])?></td><td>$<?=number_format($p['price'],2)?></td><td><?=$p['stock']?></td><td><?=$p['points_reward']?></td><td><span class="status"><?=View::e($p['status'])?></span></td><td class="actions"><a href="/admin/products/<?=$p['id']?>/edit">Editar</a><form method="post" action="/admin/products/<?=$p['id']?>/delete" data-confirm="¿Eliminar este producto?"><?=Csrf::field()?><button class="danger-link">Eliminar</button></form></td></tr><?php endforeach;?></tbody></table></div>